export const sites: Site[] = RAW_SITES.map((site, index) => ({
  id: `site-${index + 1}`,
  ...site,
  // No official tehsil/taluka master list is wired up yet, so the site's
  // own locality (already real, tied to its actual coordinates) doubles as
  // the sub-district filter value until that data is available - see the
  // Live Map's State -> District -> Tehsil picker in MapControls.tsx. This
  // is why every site here currently maps to its own single-site tehsil
  // rather than several sites sharing one administrative tehsil.
  tehsil: site.name,
}));

export const getSiteById = (id: string): Site | undefined => sites.find((s) => s.id === id);

export const circles: string[] = Array.from(new Set(sites.map((s) => s.circle))).sort();

export const states: string[] = Array.from(new Set(sites.map((s) => s.state))).sort();

export const districtsForState = (state?: string): string[] =>
  Array.from(new Set(sites.filter((s) => !state || s.state === state).map((s) => s.district))).sort();

export const tehsilsForDistrict = (state?: string, district?: string): string[] =>
  Array.from(
    new Set(
      sites
        .filter((s) => (!state || s.state === state) && (!district || s.district === district))
        .map((s) => s.tehsil)
    )
  ).sort();

export const sitesForScope = (state?: string, district?: string): Site[] =>
  sites.filter((s) => (!state || s.state === state) && (!district || s.district === district));
